//S9: 退会・個人データ消去 (削除権) — 生成時 標準装備テンプレート
// 個人情報保護法 (利用停止・消去請求への対応) / GDPR 第17条 (忘れられる権利) の土台。
//
// 設計原則:
//  - 物理削除でなく「匿名化」を既定とする。取引記録 (請求書・受注・仕訳等) には
//    法定保存義務 (法人税法 7年 等) があるため、個人を特定する情報だけを不可逆に消す。
//  - User 行は残して FK 整合を維持する (関連伝票が孤児にならない)。
//  - 消去の実施自体は監査ログへ残す (ログに PII は含めない)。
//
// 配線手順:
//  1) 退会 API: app/api/account/erase/route.ts (POST・パスワード再入力で再認証) から呼ぶ
//  2) 管理画面: ユーザー詳細に「個人データを消去」ボタン (確認ダイアログ + 理由記録)
//  3) 消去後は session-revocation.ts の revokeAllSessions() で全端末ログアウト

import crypto from 'crypto';

/** 元のメールアドレスへ戻せない匿名アドレスを生成する (unique 制約とも衝突しない) */
export function anonymizedEmail(userId: string): string {
  const h = crypto.createHash('sha256').update(userId).digest('hex').slice(0, 12);
  return `deleted-${h}@erased.invalid`;
}

export interface EraseOptions {
  /**
   * スキーマ固有の PII カラムの匿名化指定。自プロジェクトの User モデルに合わせて
   * 必ず列挙すること (例: { phone: null, address: null, birthDate: null,
   * passwordHash: crypto.randomBytes(32).toString('hex'), totpSecret: null })
   */
  extraFields?: Record<string, unknown>;
  /** 監査ログ書込 (推奨)。entry に PII は含まれない */
  writeAudit?: (entry: { action: string; targetId: string; at: Date }) => Promise<void>;
}

type UserDelegate = {
  update: (args: { where: { id: string }; data: Record<string, unknown> }) => Promise<unknown>;
};

/**
 * ユーザーの個人データを不可逆に匿名化する。
 * 使用例: await eraseUserAccount(prisma.user, userId, { extraFields: { phone: null } })
 */
export async function eraseUserAccount(
  userDelegate: UserDelegate,
  userId: string,
  opts: EraseOptions = {},
): Promise<void> {
  const data: Record<string, unknown> = {
    email: anonymizedEmail(userId),
    name: '削除済みユーザー',
    ...opts.extraFields,
  };
  await userDelegate.update({ where: { id: userId }, data });
  if (opts.writeAudit) {
    await opts.writeAudit({ action: 'PERSONAL_DATA_ERASED', targetId: userId, at: new Date() });
  }
}
